"""Build truthful manifests and deliverables from files/results that actually exist."""
import datetime,hashlib,json,pathlib,sys
import pandas as pd
import pyreadstat
ROOT=pathlib.Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from services.rules import REGISTRY
from services.importers import import_health_csv,import_activity_catalog
def read(name):return json.loads((ROOT/'reports'/name).read_text())
def dump(path,obj):(ROOT/path).write_text(json.dumps(obj,ensure_ascii=False,indent=2,default=str))
def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()
def main():
    raw=ROOT/'data/raw';downloads=read('downloads.json');sources=[]
    rights=lambda process=None,train=None,rag=None,data=None,adapter=None:{'download_process':process,'training':train,'rag':rag,'redistribute_data':data,'redistribute_adapter':adapter}
    def add(ident,title,creator,url,status,license,permissions,role,counts,notes,files,revision=None):
        sources.append({'id':ident,'name':title,'creator':creator,'url':url,'revision':revision,'status':status,'license':license,'permissions':permissions,'role':role,'counts':counts,'limitations':notes,'files':[{'file':str(p.relative_to(ROOT)) if p.is_relative_to(ROOT) else str(p),'sha256':sha(p),'bytes':p.stat().st_size} for p in files if p.is_file()],'accessed_dates':['2026-10-11','2026-10-12'],'variables_units_missing':'See corresponding reports/*-audit.json and original dictionaries; unknown definitions remain unknown'})
    ta=read('training-data-audit.json');ma=read('medquad-audit.json')
    add('medquad','MedQuAD','Asma Ben Abacha; Dina Demner-Fushman','https://github.com/abachaa/MedQuAD','used','CC-BY-4.0',rights(True,True,True,'with attribution','with attribution and base-model terms'),'Original English QA pilot only',{'candidate_qa':ma['candidate_pairs'],'prepared':ta['counts'],'actually_trained_unique_pairs':6,'persons':None},['No recovered answers from collections 10/11/12','Source comparison is not clinician review','6/1/1 is not an adequate clinical benchmark'],[raw/'medquad.tar.gz',raw/'medquad-LICENSE.txt',raw/'medquad-readme.txt'],json.loads((raw/'medquad-api.json').read_text())['sha'])
    old=pathlib.Path('/Users/tawan/Documents/Codex/2026-10-10/l')
    ha=read('hai-audit.json')
    add('hai','HAI-Coaching','Balloccu et al.; uccollab','https://github.com/uccollab/hai-coaching','excluded','Repository LGPL-2.1; dataset-specific application not clear',rights(True,None,None,None,None),'Inspection only',{'rows':ha['rows'],'expert_rows':ha['expert_rows'],'training_used':0,'persons':None},['Only struggle_original and suggestion_from_expert considered','ChatGPT candidates excluded','Local workbook revision unverified; no training rights assumed'],[old/'work/dataset-research/hai-coaching.xlsx',raw/'hai-LICENSE',raw/'hai-README.md'])
    frame,meta=pyreadstat.read_sav(raw/'figshare-data-Diabete-dataset.sav',user_missing=True)
    clean=frame.copy()
    for col,ranges in meta.missing_ranges.items():
        for rng in ranges:clean.loc[clean[col].between(rng['lo'],rng['hi']),col]=float('nan')
    dist={'n_rows':len(frame),'unique_ids':frame.ID.nunique(),'duplicate_ids':int(frame.ID.duplicated().sum()),'missing_codes':meta.missing_ranges,'nonmissing_after_codes':clean.notna().sum().to_dict(),'sleep_hours_distribution':clean.SleepHour.value_counts(dropna=False).to_dict(),'diabetes_groups':clean.Diabetes.value_counts(dropna=False).to_dict(),'measurement_provenance':{'anthropometrics':'assessed by health volunteers per article Methods; WC unit consistency unresolved','sleep_food_activity':'interviewer-administered self report','BMI_WHR':'derived in original dataset'},'period':'February–May 2016; activity questionnaire reflects retrospective usual behavior, not daily timeline','limitations':['case-control source, convenience control sampling, ages 30–85, excludes specified chronic diseases','Dictionary WC unit cm conflicts with scale of reported mean; no silent conversion','Paper WHR cutoff text typo retained as source discrepancy; no clinical rule generated']}
    dump('reports/thai-distributions.json',dist)
    clean['original_sav_row']=range(1,len(clean)+1)
    clean.to_csv(ROOT/'data/prepared/thai-behavior-clean.csv',index=False)
    ambiguous=clean.ID.duplicated(keep=False)|clean.ID.isna()
    unique=clean.loc[~ambiguous]
    unique.to_csv(ROOT/'data/prepared/thai-behavior-unambiguous-id.csv',index=False)
    mapping={'usual_sleep_hours':{'source_column':'SleepHour','unit':'h/night','method':'self_report','missing_codes':['']},'original_sav_row':{'source_column':'original_sav_row','unit':'row index (1-based)','method':'provenance','missing_codes':[]}}
    imported=import_health_csv(ROOT/'data/prepared/thai-behavior-unambiguous-id.csv','figshare-8246780-v2','ID',mapping,{'process':True})
    dump('reports/health-import-result.json',{'rows_imported':len(imported),'excluded_ambiguous_id_rows':int(ambiguous.sum()),'excluded_source_rows':clean.loc[ambiguous,'original_sav_row'].tolist(),'destination':'in-memory audit only, no user profiles or training writes','mapping':mapping,'missing_values':sum(r['values']['usual_sleep_hours']['value'] is None for r in imported),'first_attempt':'person-level importer rejected duplicate IDs; all ambiguous-ID rows quarantined, never merged or assigned new identities'})
    add('thai-behavior','Sleep and health behaviors among diabetic and non-diabetic groups','Chudchawal Juntarawijit','https://doi.org/10.6084/m9.figshare.8246780','used','CC0',rights(True,True,True,True,True),'Row distributions and unambiguous-ID importer audit only',{'rows':len(frame),'unique_identifiers':frame.ID.nunique(),'persons':None,'imported_unambiguous_id_rows':len(imported),'training_used':0},dist['limitations']+['Duplicate source IDs: person count not independently verified; all duplicate-ID rows excluded from person-level import'],list(raw.glob('figshare-*')),'2')
    za=read('zenodo-audit.json')['Sheet1']
    add('thai-literacy','Health literacy and behaviors influencing blood sugar level control','Atthawit Singsalasang','https://zenodo.org/records/6325536','inspected','CC-BY-4.0',rights(True,True,True,'with attribution','with attribution'),'Structure inspection only',{'rows':za['rows'],'columns':len(za['columns']),'training_used':0,'unique_identifiers':605,'persons':605},['605 unique IDs; consistent with article sample size; see zenodo-definition-audit.json','dmcontrol is a coded outcome; no invented raw blood glucose or medication data','Original dictionary dmcontrol 1/2 conflicts with observed 0/1; no silent recode; totalhl item-sum checked in definition audit'],list(raw.glob('zenodo*')),'record 6325536 revision 2')
    na=read('nhanes-recheck.json')
    add('nhanes','NHANES 2021–2023 local merged artifacts','CDC/NCHS; prior local research merge','https://wwwn.cdc.gov/nchs/nhanes/','used','US federal public-use data; source-specific terms apply',rights(True,True,True,'retain source notices',None),'Join cardinality verification only',{'persons':na['unique_people'],'food_rows':na['food_rows'],'food_persons':na['food_people'],'training_used':0},['US observed intake is not Thai food advice','No population estimates without appropriate weights/design','No cross-dataset subject merges'],list((old/'outputs').glob('nhanes-*.csv')),'2021–2023')
    add('thaifcd','Thai Food Composition Database','Institute of Nutrition, Mahidol University','https://inmu.mahidol.ac.th/thaifcd/home','access_pending','All rights reserved; noncommercial use with acknowledgement, other uses require permission',rights('noncommercial access',None,None,None,None),'Schema/importer only',{'food_rows_imported':0,'training_used':0},['No assumed API or bulk access','Need permission for intended app, redistribution and processing route','No fabricated nutrient/portion values'],[raw/'thaifcd.html'],'Online version 3, August 2025')
    add('nhes','NHES 7 summary','HSRI / survey partners','https://opendata.hsri.or.th/dataset/nhes7-summary','access_pending','Portal terms; microdata access unverified',rights(True,None,None,None,None),'Summary source candidate, no microdata',{'microdata_rows':0,'training_used':0},['Landing page and PDF link are not individual-level data','No participant microdata requested'],[raw/'nhes.html'],'NHES 7')
    chunks=[json.loads(x) for x in (ROOT/'data/knowledge/chunks.jsonl').read_text().splitlines()]
    add('niddk-healthy','Healthy Living with Diabetes','NIDDK/NIH','https://www.niddk.nih.gov/health-information/diabetes/overview/healthy-living-with-diabetes','used','Copyright-free NIDDK text with exceptions and attribution',rights(True,None,True,'text with attribution; no third-party graphics',None),'Exact-section RAG',{'documents':1,'chunks':len(chunks),'training_used':0},['English evidence only','No claim of NIDDK endorsement','No clinical review of individualized recommendation rules'],[raw/'niddk.html',raw/'niddk-copyright.html'])
    for ident,url,notes in [('who-activity','https://www.who.int/news-room/fact-sheets/detail/physical-activity','Read for source review; not indexed; reuse terms pending'),('cdc-sleep','https://www.cdc.gov/sleep/about/index.html','Browser source read; download returned 403; not indexed'),('dmthai','https://dmthai.org/new/index.php/activities-and-news/news-pr/naewthang-wech-ptibati-sahrab-rokh-bea-hwan-2566-chbab-prabprung-kph-67','Landing page inspected; full guideline reuse/review pending')]:
        add(ident,ident,ident,url,'candidate','not cleared for import',rights(True,None,None,None,None),'Source review only',{'training_used':0,'rag_chunks':0},[notes],[raw/(ident+'.html')])
    dump('data/source_manifest.json',{'generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'statuses':['candidate','downloaded','inspected','eligible','used','excluded','access_pending'],'sources':sources})
    dump('data/rule_registry.json',REGISTRY)
    # Exact source phrases, educational catalog only. No invented intensity/contraindications.
    activity=next(c for c in chunks if 'physical activity' in c['heading'])
    catalog=[]
    for ident,phrase in [('walking','Walking briskly'),('swimming','swimming')]:
        if phrase.lower() in activity['text'].lower():
            catalog.append({'activity_id':'niddk-'+ident,'name':phrase,'type':'source_activity_example','intensity_definition':None,'source_url':activity['url'],'source_location':activity['location'],'source_chunk_id':activity['chunk_id'],'equipment':None,'location':None,'conditions':'Only schedule user-confirmed activities; new activity requires professional assessment as described in source','contraindications':None,'review_status':'draft','recommendation_enabled':False})
    dump('data/catalog/activities.json',catalog);import_activity_catalog(ROOT/'data/catalog/activities.json')
    notebook={'nbformat':4,'nbformat_minor':5,'metadata':{'kernelspec':{'display_name':'Python 3 (local .venv)','language':'python','name':'python3'}},'cells':[]}
    for typ,text in [('markdown','# ฝึกและประเมินบน Mac\nใช้ kernel จาก .venv ของโครงการ ไม่มีผลรันที่สร้างขึ้น งานยาวให้เรียก scripts จาก Terminal; ไม่ผูกอายุ process กับ notebook'),('code','from pathlib import Path\nimport os, sys, subprocess\nroot = Path.cwd()\nif root.name == "notebooks": root = root.parent\nos.chdir(root)\nprint(root, sys.executable)'),('code','subprocess.run([sys.executable, "scripts/check_environment.py"], check=True)'),('markdown','## ตรวจข้อมูลและสิทธิก่อนฝึก\nอ่าน data/source_manifest.json และ reports/training-data-audit.json ก่อนเลือกข้อมูลใหม่ ห้ามใช้ข้อมูลผู้ใช้หรือ software fixtures ฝึก'),('code','import json\nprint(json.loads(Path("reports/training-data-audit.json").read_text())["counts"])'),('code','subprocess.run([sys.executable, "scripts/prepare_training.py"], check=True)'),('markdown','## คำสั่งที่รันใน Terminal\n```bash\n.venv/bin/python scripts/train.py --config models/pilot.yaml\n.venv/bin/python scripts/evaluate.py\n.venv/bin/python scripts/run_demo.py\n```\nการรันซ้ำ pilot จะเขียนผลใน adapters/pilot; เปลี่ยน adapter_path หากต้องเก็บการทดลองเดิม'),('code','base=json.loads(Path("reports/evaluation-base.json").read_text())\nadapter=json.loads(Path("reports/evaluation-adapter.json").read_text())\nprint({"base_loss":base["heldout_loss"],"adapter_loss":adapter["heldout_loss"],"test_count":base["test_count"]})')]:
        cell={'cell_type':typ,'id':hashlib.sha256(text.encode()).hexdigest()[:12],'metadata':{},'source':text.splitlines(keepends=True)}
        if typ=='code':cell|={'execution_count':None,'outputs':[]}
        notebook['cells'].append(cell)
    dump('local_training.ipynb',notebook)
    print('Generated manifest, real-data import/distribution audit, rules, activity catalog and notebook')
if __name__=='__main__':main()
